/**
 * Unit tests for BeanDeserializerBase#deserializeFromObjectId.
 * Note: Since the method is protected, we use a Testable subclass.
 */
public class BeanDeserializerBase_deserializeFromObjectId_TriageGen0Test {

    private TestableBeanDeserializer deserializer;
    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private ObjectIdReader mockObjectIdReader;
    private ReadableObjectId mockReadableObjectId;
    private JsonGenerator mockGenerator;

    // Testable subclass to access protected method and inject dependencies
    private static class TestableBeanDeserializer extends BeanDeserializerBase {
        private final Class<?> beanType;

        protected TestableBeanDeserializer(ObjectIdReader oir, Class<?> beanType) {
            super(null, oir);
            this.beanType = beanType;
        }

        @Override
        public JsonDeserializer<Object> unwrappingDeserializer(com.fasterxml.jackson.databind.NameTransformer unwrapper) {
            return null;
        }

        @Override
        public abstract JsonDeserializer<Object> createContextual(DeserializationContext ctxt, com.fasterxml.jackson.databind.JsonDeserializer.Context context);

        @Override
        public abstract JsonDeserializer<?> createContextual(DeserializationContext ctxt, com.fasterxml.jackson.databind.PropertyName property);

        // Implementation of abstract methods required by the class structure
        @Override public JsonDeserializer<Object> createContextual(DeserializationContext ctxt, com.fasterxml.jackson.databind.JsonDeserializer.Context context) { return null; }
        @Override public JsonDeserializer<?> createContextual(DeserializationContext ctxt, com.fasterxml.jackson.databind.PropertyName property) { return null; }
        @Override protected BeanDeserializerBase asArrayDeserializer() { return null; }
        @Override public Object deserializeFromObject(JsonParser p, DeserializationContext ctxt) throws IOException { return null; }
        @Override protected Object _deserializeUsingPropertyBased(JsonParser p, DeserializationContext ctxt) throws IOException, com.fasterxml.jackson.core.JsonProcessingException { return null; }
        @Override public void resolve(DeserializationContext ctxt) throws JsonMappingException {}

        // Accessor for the protected method under test
        public Object callDeserializeFromObjectId(JsonParser p, DeserializationContext ctxt) throws IOException {
            return deserializeFromObjectId(p, ctxt);
        }

        // Overriding to simulate the _beanType field access if it were accessible or via reflection
        // In the provided snippet, _beanType is used in the exception message. 
        // Since we can't easily change the private field without reflection, we rely on the logic.
    }

    // Mock interface for JsonGenerator as it's required by ObjectIdReader
    interface JsonGenerator extends com.fasterxml.jackson.core.JsonGenerator {
        @Override JsonLocation getCurrentLocation();
    }

    @Before
    public void setUp() throws IOException {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockObjectIdReader = mock(ObjectIdReader.class);
        mockReadableObjectId = mock(ReadableObjectId.class);
        mockGenerator = mock(JsonGenerator.class);

        // Setup the reader and generator
        when(mockObjectIdReader.generator).thenReturn(mockGenerator);
        when(mockObjectIdReader.resolver).thenReturn(null); // Can be null as per signature

        deserializer = new TestableBeanDeserializer(mockObjectIdReader, Object.class);

        // Mock JsonLocation for exception testing
        JsonLocation mockLocation = mock(JsonLocation.class);
        when(mockParser.getCurrentLocation()).thenReturn(mockLocation);
    }

    @Test
    public void testDeserializeFromObjectId_Success() throws IOException {
        // Arrange
        Object expectedPojo = new Object();
        Object id = "id-123";

        when(mockObjectIdReader.readObjectReference(mockParser, mockContext)).thenReturn(id);
        when(mockContext.findObjectId(eq(id), any(), any())).thenReturn(mockReadableObjectId);
        when(mockReadableObjectId.resolve()).thenReturn(expectedPojo);

        // Act
        Object result = deserializer.callDeserializeFromObjectId(mockParser, mockContext);

        // Assert
        assertEquals(expectedPojo, result);
        verify(mockObjectIdReader).readObjectReference(mockParser, mockContext);
        verify(mockContext).findObjectId(eq(id), eq(mockGenerator), any());
        verify(mockReadableObjectId).resolve();
    }

    @Test(expected = UnresolvedForwardReference.class)
    public void testDeserializeFromObjectId_ThrowsUnresolvedForwardReference() throws IOException {
        // Arrange
        Object id = "id-unresolved";
        when(mockObjectIdReader.readObjectReference(mockParser, mockContext)).thenReturn(id);
        when(mockContext.findObjectId(eq(id), any(), any())).thenReturn(mockReadableObjectId);
        // Simulate that the object is not yet resolved
        when(mockReadableObjectId.resolve()).thenReturn(null);

        // Act
        deserializer.callDeserializeFromObjectId(mockParser, mockContext);

        // Assert handled by expected exception
    }

    @Test
    public void testDeserializeFromObjectId_VerifyExceptionMessageContent() throws IOException {
        // This test ensures the exception path is fully covered and uses the parameters correctly.
        // Arrange
        Object id = "999";
        when(mockObjectIdReader.readObjectReference(mockParser, mockContext)).thenReturn(id);
        when(mockContext.findObjectId(eq(id), any(), any())).thenReturn(mockReadableObjectId);
        when(mockReadableObjectId.resolve()).thenReturn(null);

        // Act & Assert
        try {
            deserializer.callDeserializeFromObjectId(mockParser, mockContext);
        } catch (UnresolvedForwardReference e) {
            // Check if the message contains the ID
            assert(e.getMessage().contains("999"));
            // Verify location was passed
            verify(mockParser).getCurrentLocation();
            verify(mockReadableObjectId).resolve();
        }
    }
}
